  "content.c1": "सुलभता का परिचय",
  "content.c1d": "WCAG गाइडलाइन्स, सहायक तकनीकों, और समावेशी डिज़ाइन की बुनियादी बातों को कवर करने वाला एक व्यापक कोर्स।",
  "content.c2": "स्क्रीन रीडर में महारत",
  "content.c2d": "NVDA, JAWS और VoiceOver स्क्रीन रीडर का उपयोग करके उपकरणों को आत्मविश्वास से नेविगेट करना सीखें।",
  "content.c3": "ब्रेल साक्षरता की बुनियादें",
  "content.c3d": "शुरुआत करने वालों के लिए संरचित पाठों के साथ ब्रेल पढ़ना और लिखना शुरू करें।",
  "content.c4": "एडैप्टिव टेक्नोलॉजी वर्कशॉप",
  "content.c4d": "मैग्नीफायर, वॉइस असिस्टेंट और स्मार्ट सुलभता टूल्स के साथ व्यावहारिक प्रशिक्षण।",
  "content.a1": "सुलभता के साथ शुरुआत कैसे करें",
  "content.a1d": "दिन 1 से ही अपनी डिजिटल ज़िंदगी को ज़्यादा सुलभ बनाने के लिए आवश्यक सुझाव।",
  "content.a2": "रंग कंट्रास्ट की सर्वश्रेष्ठ प्रथाएँ",
  "content.a2d": "सही रंग कंट्रास्ट हर किसी के लिए पठनीयता कैसे बेहतर बनाता है।",
  "content.a3": "कीबोर्ड नेविगेशन पैटर्न",
  "content.a3d": "कुशल ब्राउज़िंग के लिए कीबोर्ड शॉर्टकट्स और टैब नेविगेशन में महारत हासिल करें।",
  "content.a4": "समावेशी डिज़ाइन सिद्धांत",
  "content.a4d": "ऐसी डिज़ाइन सोच रणनीतियाँ जो सुलभता को केंद्र में रखती हैं।",
  "content.a5": "ARIA लेबल्स को सही तरीके से करें",
  "content.a5d": "सार्थक ARIA गुणों और स्क्रीन रीडर सपोर्ट के लिए डेवलपर गाइड।",
  "content.p1": "आज की सुलभता",
  "content.p1d": "सुलभता समर्थकों, टेक लीडर्स और उपयोगकर्ताओं के साथ साप्ताहिक बातचीत।",
  "content.p2": "समावेशी आवाज़ें",
  "content.p2d": "दुनिया भर में दृष्टिबाधित व्यक्तियों की कहानियाँ और अनुभव।",
  "content.p3": "बिना बाधाओं की टेक्नोलॉजी",
  "content.p3d": "यह तलाशना कि उभरती तकनीक विकलांग लोगों के लिए बाधाएँ कैसे हटा रही है।",
  "content.m1": "ऑडियो-डिस्क्राइब्ड डॉक्यूमेंट्रीज़",
  "content.m1d": "इमर्सिव अनुभव के लिए पूर्ण ऑडियो विवरणों के साथ डॉक्यूमेंट्रीज़।",
  "content.m2": "साइन लैंग्वेज ट्यूटोरियल",
  "content.m2d": "कैप्शनयुक्त, हाई-कॉन्ट्रास्ट वीडियो पाठों के साथ साइन लैंग्वेज सीखें।",
  "content.m3": "सुलभ कोडिंग ट्यूटोरियल",
  "content.m3d": "स्क्रीन रीडर उपयोगकर्ताओं के लिए बनाए गए चरण-दर-चरण कोडिंग पाठ।",
