  "jungle.howTo.1": "आप जंगल में फँसे हैं — सर्वाइवल के चुनाव करें",
  "jungle.howTo.2": "हर चुनाव आपके HP और स्कोर को अलग तरह से प्रभावित करता है",
  "jungle.howTo.3": "अगर आपका HP 0 तक पहुँच जाए, तो गेम खत्म हो जाएगा",
  "jungle.howTo.4": "जीतने के लिए सभी 8 परिदृश्य पूरे करें!",
  "jungle.scene6": "आपको एक घायल पक्षी मिलता है। आप क्या करेंगे?",
  "jungle.s6c1": "ध्यान से उठाकर ले जाएँ — इससे आपको रास्ता मिल सकता है (+5 HP, +25 पॉइंट्स)",
  "jungle.s6c2": "छोड़ दें — इसकी देखभाल में ऊर्जा बर्बाद होगी (0 HP, +10 पॉइंट्स)",
  "jungle.scene7": "एक नदी आपके रास्ते में आ जाती है। पानी तेज़ लग रहा है।",
  "jungle.s7c1": "गिरे हुए लट्ठों से राफ्ट बनाएं (−5 HP, +40 पॉइंट्स)",
  "jungle.s7c2": "ऊपर की ओर चलकर उथला रास्ता खोजें (+10 HP, +20 पॉइंट्स)",
  "jungle.scene8": "दूर से धुआँ दिखता है।",
  "jungle.s8c1": "धुएँ की ओर जाएँ — शायद बचाव हो! (+15 HP, +45 पॉइंट्स)",
  "jungle.s8c2": "इसे टालें — शायद जंगल की आग हो (−5 HP, +15 पॉइंट्स)",
  "jungle.scene9": "रात हो रही है। आपको शरण चाहिए।",
  "jungle.s9c1": "शिकारियों से बचने के लिए एक ऊँचे पेड़ पर चढ़ें (+10 HP, +30 पॉइंट्स)",
  "jungle.s9c2": "टहनियों से ज़मीन पर शरण बनाएं (−5 HP, +35 पॉइंट्स)",
  "jungle.scene10": "आपको एक ऐसा फल मिलता है जिसे आप नहीं पहचानते। आपको बहुत भूख लगी है।",
  "jungle.s10c1": "खाकर देखें — आप तड़प रहे हैं! (−20 HP, +30 पॉइंट्स)",
  "jungle.s10c2": "पहले त्वचा पर थोड़ा सा टेस्ट करें (0 HP, +20 पॉइंट्स)",
  "jungle.scene11": "रास्ते पर एक बड़ी साँप कुंडली मारकर बैठी है।",
  "jungle.s11c1": "धीरे-धीरे पीछे हटें और रास्ता बदलकर देखें (+5 HP, +30 पॉइंट्स)",
  "jungle.s11c2": "डराने की कोशिश करें (−25 HP, +40 पॉइंट्स)",
  "jungle.scene12": "आपको झरना सुनाई देता है — आपके पानी के स्रोत बेहद कम हैं।",
  "jungle.s12c1": "ताज़ा पानी पाने के लिए आवाज़ का पीछा करें (+20 HP, +35 पॉइंट्स)",
  "jungle.s12c2": "इसे अनदेखा करें और आगे बढ़ते रहें (−15 HP, +20 पॉइंट्स)",
  "jungle.scene13": "तेज़ी से तूफ़ान पास आ रहा है।",
  "jungle.s13c1": "ऊँची जगह ढूँढें और कवर लें (+10 HP, +25 पॉइंट्स)",
  "jungle.s13c2": "भागने के लिए चलते रहें (−10 HP, +30 पॉइंट्स)",
  "jungle.scene14": "आपको एक गुफा मिलती है। अब अँधेरा हो रहा है।",
  "jungle.s14c1": "शरण के लिए गुफा में प्रवेश करें (+15 HP, +30 पॉइंट्स)",
  "jungle.s14c2": "पेड़ के नीचे सो जाएँ — हो सकता है गुफा में कोई हो (+5 HP, +20 पॉइंट्स)",
  "jungle.scene15": "आप थक चुके हैं। आगे खुला क्षेत्र सुरक्षित लगता है।",
  "jungle.s15c1": "आराम करें और फिर से ताक़त पाएं (+20 HP, +20 पॉइंट्स)",
  "jungle.s15c2": "आगे बढ़ें — यहाँ आराम करना खतरनाक है (−5 HP, +30 पॉइंट्स)",
  "jungle.scene16": "आपको एक पुराने नक्शे के निशान एक पेड़ पर उकेरे हुए मिलते हैं।",
  "jungle.s16c1": "नक्शे की दिशा में चलें (+5 HP, +40 पॉइंट्स)",
  "jungle.s16c2": "इसे अनदेखा करें — हो सकता है ये पुराना हो (0 HP, +10 पॉइंट्स)",
  "jungle.scene17": "जंगली सूअर आक्रामक तरीके से आपके रास्ते में आ जाते हैं।",
  "jungle.s17c1": "तुरंत पास के पेड़ पर चढ़ें (+5 HP, +30 पॉइंट्स)",
  "jungle.s17c2": "अपनी जगह टिके रहें और चिल्लाएँ (−20 HP, +35 पॉइंट्स)",
  "jungle.scene18": "आपको सामान वाला एक परित्यक्त कैंप मिलता है।",
  "jungle.s18c1": "जो भी उपयोगी हो सब ले लें (+20 HP, +50 पॉइंट्स)",
  "jungle.s18c2": "छोड़ दो—शायद किसी को बाद में इसकी ज़रूरत पड़े (0 HP, +10 pts)",
  "jungle.scene19": "एक बंदर आपका खाने वाला बैग चुरा लेता है!",
  "jungle.s19c1": "बंदर का पीछा करो (−10 HP, +40 pts)",
  "jungle.s19c2": "छोड़ दो—ऊर्जा खर्च करने लायक नहीं (+0 HP, +15 pts)",
  "jungle.scene20": "तुम्हें ऊपर से हेलीकॉप्टर की आवाज़ सुनाई देती है।",
  "jungle.s20c1": "तुरंत संकेत देने वाली आग जलाओ! (+30 HP, +60 pts)",
  "jungle.s20c2": "हाथ हिलाओ—हो सकता है वह तुम्हें देख ले (+5 HP, +40 pts)",
  "tactical.combo": "🔥 कॉम्बो ×{n}!",
  "tactical.gift": "🎁 बोनस टारगेट!",
