  "akinator.char.messi": "लियोनेल मेस्सी",
  "akinator.howTo.1": "किसी भी असली या काल्पनिक किरदार के बारे में सोचो",
  "akinator.howTo.2": "प्रश्नों का ईमानदारी से जवाब दो (हाँ/शायद/पता नहीं/शायद नहीं/नहीं)",
  "akinator.howTo.3": "हर जवाब के साथ AI संभावित विकल्पों को कम करता है",
  "akinator.howTo.4": "देखो क्या Akinator 20 सवालों के अंदर तुम्हारे किरदार का अनुमान लगा सकता है!",
  "neonbreach.howTo.1": "जलाए गए नोड्स की सीक्वेंस को ध्यान से देखो",
  "neonbreach.howTo.2": "फिर टैप करके उसी बिल्कुल समान सीक्वेंस को दोहराओ",
  "neonbreach.howTo.3": "हर सही लेवल याद रखने के लिए एक और नोड जोड़ता है",
  "neonbreach.howTo.4": "एक गलत टैप और फ़ायरवॉल तुम्हें पकड़ लेगा!",
  "earmaster.howTo.1": "बजाए जा रहे संगीत नोट को ध्यान से सुनो",
  "earmaster.howTo.2": "7 विकल्पों में से वह नोट चुनो जो तुम्हें सुनाई दिया",
  "earmaster.howTo.3": "नोट को एक बार फिर से चलाने के लिए Play बटन का उपयोग करो",
  "earmaster.howTo.4": "अंतिम स्कोर देखने के लिए 10 राउंड पूरे करो",
  "uno.howTo.1": "डोमिनो चेन के सिरों पर दिए नंबर/रंग से मेल करो",
  "uno.howTo.2": "जिस कार्ड को खेलना है, उसे अपने हाथ से टैप करो",
  "uno.howTo.3": "अगर कोई मैच नहीं है, तो कार्ड जोड़ने के लिए Draw पर टैप करो",
  "uno.howTo.4": "सबसे पहले अपना हाथ खाली करने वाला जीतेगा!",
  "briscola.howTo.1": "ब्रिस्कोला एक इतालवी ट्रिक-टेकिंग कार्ड गेम है",
  "briscola.howTo.2": "ट्रम्प सूट (ब्रिस्कोला) सभी अन्य सूट्स को मात देता है",
  "briscola.howTo.3": "ट्रिक जीतकर पॉइंट्स कमाओ—Ace=11, 3=10, King=4, Queen=3, Jack=2",
  "briscola.howTo.4": "सभी कार्ड खेलने के बाद सबसे अधिक स्कोर जीतता है",
  "card99.howTo.1": "कार्ड खेलो ताकि रनिंग टोटल 99 या उससे कम रहे",
  "card99.howTo.2": "स्पेशल कार्ड: King=0, Queen=hold, Jack=−10, Ace=1 या 11",
  "card99.howTo.3": "टोटल 99 से ऊपर करोगे तो एक लाइफ हार जाओगे",
  "card99.howTo.4": "लाइफ्स के साथ सबसे आख़िरी में खड़ा रहने वाला जीतेगा!",
  "dominoes.howTo.1": "डोमिनो चेन के सिरों के नंबरों से मैच करो",
  "dominoes.howTo.2": "अपने हाथ से ऐसे टाइल्स चलाओ जो खुले सिरे से मेल खाते हों",
  "dominoes.howTo.3": "अगर तुम नहीं खेल सकते, तो पाइल से ड्रॉ करो",
  "dominoes.howTo.4": "सबसे पहले अपना हाथ खाली करने वाला (या सबसे कम पिप टोटल) जीतेगा!",
  "farkle.howTo.1": "6 पासे रोल करो और किसी भी स्कोरिंग पासे को अलग रखो",
  "farkle.howTo.2": "1s = 100 pts · 5s = 50 pts · थ्री-ऑफ-ए-काइंड = फेस × 100",
  "farkle.howTo.3": "अगर किसी रोल पर NO पासे स्कोर करते हैं, तो वह FARKLE है—तुम अपनी बारी खो दोगे!",
  "farkle.howTo.4": "अपने पॉइंट्स सुरक्षित रखो ताकि वे बने रहें, या अधिक रिस्क/रिवार्ड के लिए फिर से रोल करो",
  "quiz.howTo.1": "जितनी जल्दी हो सके 20 मल्टीपल-चॉइस सवालों के जवाब दो",
  "quiz.howTo.2": "हर सवाल के लिए 3 सेकंड—जल्दी जवाब दो!",
  "quiz.howTo.3": "तेज़ और सही जवाब ज्यादा बोनस पॉइंट्स दिलाते हैं",
  "quiz.howTo.4": "अंतिम रैंक देखने के लिए सभी सवाल पूरे करो",
  "memory.howTo.1": "मैचिंग जोड़े खोजने के लिए एक साथ 2 कार्ड पलटाओ",
  "memory.howTo.2": "अगर वे मैच करते हैं, तो वे ऊपर की तरफ ही रहते हैं",
  "memory.howTo.3": "अगर नहीं, तो दोनों वापस नीचे पलट जाते हैं—याद रखो वे कहाँ थे!",
  "memory.howTo.4": "जितनी कम चालों में हो सके, सभी जोड़े मैच करके हाई स्कोर करो",
